.card--testimonial-v26 {
    border-top: 5px solid $color-nearblack;
    padding-top: 15px;
    &.card {
        //Makding specific to override the .card styles
        margin: 0;
    }

    &__video {
    }
    &__quote {
        margin: 0;
        padding-top: 0;
        p {
            font-size: 30px;
        }
    }
    .embedded-video-v26 {
        padding: 0;
    }

    &__author {
        display: flex;
        gap: 12px;
        font-size: 14px;
    }

    &__thumbnail {
        display: block;
        width: 48px;
        height: 48px;
        border-radius: $border-radius-round;
    }
    &__name {
        color: $color-red50;
        display: block;
        font-weight: $font-weight-bold;
    }
    &__caption {
        font-size: 14px;
        font-weight: $font-weight-bold;
    }
}
